    for j in range(n_boats):
        model += cp.sum([visits[i][j][k] for k in range(n_periods)]) <= 1  # A guest boat cannot revisit a host

for i in range(n_boats):
    for k in range(n_periods):
        model += cp.sum([visits[i][j][k] for j in range(n_boats)]) <= 1  # A guest boat can only visit one host per period

