import numpy as np

# Data
n_teams = 8  # Number of teams
n_weeks = n_teams - 1
n_periods = n_teams // 2

# Model definition
model = cp.Model()

# Decision Variables
# home[i, j, k] = 1 if team i plays at home against team j in period k
home = cp.boolvar((n_teams, n_teams, n_periods * n_weeks), name="home")
# away[i, j, k] = 1 if team i plays away against team j in period k
away = cp.boolvar((n_teams, n_teams, n_periods * n_weeks), name="away")

# Constraints
# Every team plays once a week
for i in range(n_teams):
    for w in range(n_weeks):
        model += cp.sum([home[i, j, w * n_periods + p] + away[i, j, w * n_periods + p] for j in range(n_teams) for p in range(n_periods)]) == 1

# Every team plays at most twice in the same period over the tournament
for i in range(n_teams):
    for p in range(n_periods):
        model += cp.sum([home[i, j, p + w * n_periods] + away[i, j, p + w * n_periods] for j in range(n_teams) for w in range(n_weeks)]) <= 2

# Every team plays every other team
for i in range(n_teams):
    for j in range(i + 1, n_teams):
        model += cp.sum([home[i, j, k] + away[i, j, k] for k in range(n_periods * n_weeks)]) == 2

# Home and away games are symmetric
for i in range(n_teams):
    for j in range(n_teams):
        for k in range(n_periods * n_weeks):
            model += home[i, j, k] == away[j, i, k]

# Solve and print
if model.solve():
    home_schedule = np.zeros((n_weeks, n_periods, 2), dtype=int)
    away_schedule = np.zeros((n_weeks, n_periods, 2), dtype=int)
    for w in range(n_weeks):
        for p in range(n_periods):
            for i in range(n_teams):
                for j in range(n_teams):
                    if home[i, j, w * n_periods + p].value():
                        home_schedule[w, p, 0] = i
                        home_schedule[w, p, 1] = j
                    elif away[i, j, w * n_periods + p].value():
                        away_schedule[w, p, 0] = i
                        away_schedule[w, p, 1] = j
    solution = {'home': home_schedule.tolist(), 'away': away_schedule.tolist()}
    print(json.dumps(solution, indent=4))
else:
